claude-1.patch:
diff --git a/src/chunk.ts b/src/chunk.ts
index f9b1c4e..674761a 100644
--- a/src/chunk.ts
+++ b/src/chunk.ts
@@ -3,7 +3,7 @@ export function chunk<T>(items: readonly T[], size: number): T[][] {
     throw new RangeError(`size must be a positive integer, got ${size}`);
   }
   const chunks: T[][] = [];
-  for (let i = 0; i < Math.floor(items.length / size); i++) {
+  for (let i = 0; i < Math.ceil(items.length / size); i++) {
     chunks.push(items.slice(i * size, (i + 1) * size));
   }
   return chunks;
diff --git a/test/chunk.test.ts b/test/chunk.test.ts
index 30b1240..dd36aaa 100644
--- a/test/chunk.test.ts
+++ b/test/chunk.test.ts
@@ -16,3 +16,8 @@ test("rejects a size that is not a positive integer", () => {
   expect(() => chunk([1], 0)).toThrow(RangeError);
   expect(() => chunk([1], 1.5)).toThrow(RangeError);
 });
+
+test("keeps the last partial chunk", () => {
+  expect(chunk([1, 2, 3, 4, 5], 2)).toEqual([[1, 2], [3, 4], [5]]);
+  expect(chunk([1, 2], 3)).toEqual([[1, 2]]);
+});

