diff --git a/src/chunk.ts b/src/chunk.ts
index f9b1c4e..f2860ec 100644
--- a/src/chunk.ts
+++ b/src/chunk.ts
@@ -3,8 +3,8 @@ export function chunk<T>(items: readonly T[], size: number): T[][] {
     throw new RangeError(`size must be a positive integer, got ${size}`);
   }
   const chunks: T[][] = [];
-  for (let i = 0; i < Math.floor(items.length / size); i++) {
-    chunks.push(items.slice(i * size, (i + 1) * size));
+  for (let i = 0; i < items.length; i += size) {
+    chunks.push(items.slice(i, i + size));
   }
   return chunks;
 }
